import os, json, shutil, hashlib
root = "E:\\0zhongqi"
q = os.path.join(root, "_QUARANTINE_20261027")
scaf = set([".git", "code", "docs", "results", "skills", "sources", "_watch"])
def sha1(p):
    h = hashlib.sha1()
    with open(p, "rb") as f:
        for b in iter(lambda: f.read(1048576), b""):
            h.update(b)
    return h.hexdigest()[:12]
known = {}
for base in ("zhongqi_out", "zhongqi-arena_out"):
    bp = os.path.join(root, base)
    for dp, dn, fn in os.walk(bp):
        for f in fn:
            fp = os.path.join(dp, f)
            try: known[sha1(fp)] = os.path.relpath(fp, root)
            except Exception: pass
restored = []
for d in ("zhongqi", "zhongqi-arena"):
    dp = os.path.join(q, d)
    for name in sorted(os.listdir(dp)):
        if name in scaf: continue
        sp = os.path.join(dp, name)
        if not os.path.isdir(sp): continue
        dst = os.path.join(root, d + "-" + name)
        base = dst; i = 2
        while os.path.exists(base):
            base = dst + "_" + str(i); i += 1
        shutil.move(sp, base)
        files = []
        for f in sorted(os.listdir(base)):
            fp = os.path.join(base, f)
            if os.path.isfile(fp):
                try: h = sha1(fp)
                except Exception: h = "ERR"
                files.append([f, os.path.getsize(fp), known.get(h, "UNIQUE")])
        restored.append([sp, base, files])
final = []
for name in sorted(os.listdir(root)):
    p = os.path.join(root, name)
    if os.path.isdir(p):
        tot = 0; n = 0
        for dp2, dn2, fn2 in os.walk(p):
            for f in fn2:
                try: tot += os.path.getsize(os.path.join(dp2, f)); n += 1
                except Exception: pass
        final.append([name, "DIR", round(tot/1048576, 1), n])
    else:
        final.append([name, "FILE", round(os.path.getsize(p)/1048576, 2)])
print(json.dumps({"restored": restored, "final": final}, ensure_ascii=True))
